function exoModel(I, sc) { const out = []; let begin = I.p0, prev = null; for (let m = 1; m <= 36; m++) { const ch = Math.max(0, Math.min(1, I.churn + (sc ? I.dChurn : 0))); const ex = begin * ch, end = begin - ex + I.newp; const prod = I.gmv * Math.pow(1 + I.growth, m - 1); const gross = ((begin + end) / 2) * prod; const net = gross - gross * I.refund; const tk = Math.max(0, Math.min(1, I.take + (sc ? I.dTake : 0))); const fee = net * tk; const cont = fee - net * I.varc; const noc = cont - I.fixed - I.prog; const inc = cont - net * I.cfMult * (I.cfTake - I.varc); const dTk = prev === null ? 0 : tk - prev; prev = tk; const alert = I.complete !== 1 ? 'DATA BLOCKED' : begin < I.minP ? 'INSUFFICIENT COHORT' : ch > I.churnAlert || dTk < -I.takeDrop ? 'REVIEW' : 'OK'; out.push({ m, begin, ch, end, gross, net, tk, fee, cont, noc, inc, prog: I.prog, alert }); begin = end; } return out; }
function exoEvaluateAlerts(current, previous, rules) {
  if (!current.complete || !previous.complete || current.currency !== previous.currency) return [{ kind: 'data_quality', state: 'blocked' }];
  if (!Number.isFinite(current.ageSeconds) || current.ageSeconds > rules.maxAgeSeconds) return [{ kind: 'data_quality', state: 'stale' }];
  const alerts = [];
  if (current.startingPartners >= rules.minPartners && current.startingPartners > 0) { const churn = current.exitedStartingPartners / current.startingPartners; if (churn > rules.churnLimit) alerts.push({ kind: 'partner_churn', value: churn }); }
  if (current.netGMV >= rules.minGMV && previous.netGMV >= rules.minGMV && current.netGMV > 0 && previous.netGMV > 0) { const delta = current.netFees / current.netGMV - previous.netFees / previous.netGMV; if (delta < -rules.takeDropLimit) alerts.push({ kind: 'take_rate_drop', value: delta }); }
  return alerts.map((a) => ({ ...a, state: 'candidate', policyVersion: rules.version, dedupeKey: [current.scopeId, current.period, a.kind, rules.version].join(':') }));
}
