    <div className="card scrollx"><div className="lbl">3-year review</div><table className="t"><thead><tr><th>Model</th><th>Year</th><th>Gross GMV</th><th>Net GMV</th><th>Net fees</th><th>Contribution</th><th>Program spend</th><th>Net op. contribution</th><th>Program ROI</th><th>Fees vs base</th></tr></thead><tbody>{[['Base', B], ['Scenario', S]].flatMap(([n, a]) => [1, 2, 3].map((y) => { const r = yr(a, y), b = yr(B, y); return <tr key={n + y}><td><b>{n}</b></td><td>{y}</td><td className="mono">{$(r.gross)}</td><td className="mono">{$(r.net)}</td><td className="mono">{$(r.fee)}</td><td className="mono">{$(r.cont)}</td><td className="mono">{$(r.prog)}</td><td className="mono" style={r.noc < 0 ? { color: 'var(--status-danger)' } : null}>{$(r.noc)}</td><td className="mono">{r.roi === null ? '—' : (r.roi * 100).toFixed(1) + '%'}</td><td className="mono">{n === 'Base' ? '—' : $(r.fee - b.fee)}</td></tr>; }))}</tbody></table><p className="muted" style={{ margin: 0, fontSize: 12 }}>Scenario changes are independent: no demand response to the take-rate change is modelled.</p></div>
